mapper.sql:
SELECT created_at
FROM ${table}
WHERE member_id = #{memberId}
  AND ${parentColumn} IS NULL
  AND created_at > #{createdAfter}
ORDER BY created_at
LIMIT #{limit}

SELECT id AS image_id, object_key, ${thumbnailColumn} AS thumbnail_key
FROM ${table}
WHERE ${parentColumn} IS NULL
  AND created_at < #{createdBefore}
ORDER BY id
LIMIT #{limit}

DELETE FROM ${table}
WHERE id = #{imageId}
  AND ${parentColumn} IS NULL
